import React,{useEffect,useMemo,useRef,useState} from 'react';
import {createRoot} from 'react-dom/client';
import * as faceapi from '@vladmandic/face-api';
import {LayoutDashboard,Users,ClipboardList,Dumbbell,WalletCards,CalendarDays,BarChart3,Settings,LogOut,Bell,Plus,Search,ChevronRight,UserRound,Package,BriefcaseBusiness,ScanFace,ShieldCheck,Clock3,ArrowUpRight,ArrowDownRight,X,CheckCircle2,AlertTriangle,RefreshCw,Menu,MoreHorizontal,UserPlus,ReceiptText,LockKeyhole,Trash2} from 'lucide-react';
import {api,get,post,put,del} from './api';
import './styles.css';

type User={id:string;gym_id:string;name:string;email:string;role:string;gym_name:string};
type Page='dashboard'|'students'|'plans'|'enrollments'|'workouts'|'finance'|'products'|'services'|'sales'|'cash'|'checkin'|'agenda'|'reports'|'settings'|'team';
const money=(v:any)=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const date=(v:any)=>v?new Date(v).toLocaleDateString('pt-BR'): '-';
const time=(v:any)=>v?new Date(v).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}):'-';
const initial=(s:string)=>s.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();

function Toast({msg,onClose}:{msg:string,onClose:()=>void}){return <div className="toast"><CheckCircle2 size={18}/><span>{msg}</span><button onClick={onClose}><X size={16}/></button></div>}
function Modal({title,children,onClose,wide=false}:{title:string;children:React.ReactNode;onClose:()=>void;wide?:boolean}){return <div className="modal-backdrop"><div className={`modal ${wide?'modal-wide':''}`}><div className="modal-head"><h2>{title}</h2><button className="icon-btn" onClick={onClose}><X/></button></div>{children}</div></div>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="field"><span>{label}</span>{children}</label>}
function Button({children,onClick,kind='primary',type='button',disabled=false}:{children:React.ReactNode;onClick?:()=>void;kind?:string;type?:'button'|'submit';disabled?:boolean}){return <button disabled={disabled} type={type} onClick={onClick} className={`btn ${kind}`}>{children}</button>}
function Empty({title,desc,action}:{title:string;desc:string;action?:React.ReactNode}){return <div className="empty"><div className="empty-icon"><Dumbbell/></div><h3>{title}</h3><p>{desc}</p>{action}</div>}

function Auth({onLogin}:{onLogin:(u:User)=>void}){const [mode,setMode]=useState<'login'|'register'>('login'); const [b,setB]=useState<any>({}); const [busy,setBusy]=useState(false); const [err,setErr]=useState('');
 const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setErr('');try{const r=mode==='login'?await post('/auth/login',b):await post('/auth/register',b);localStorage.setItem('multigym_token',r.token);onLogin(r.user);}catch(e:any){setErr(e.message)}finally{setBusy(false)}};
 return <div className="auth"><div className="auth-art"><div className="brand big"><b>MG</b><span>MultiGym<small>Sistema para academias</small></span></div><div><h1>Gestão profissional.<br/>Operação simples.</h1><p>Alunos, matrículas, treinos, check-in, vendas e financeiro em um só lugar.</p></div><div className="auth-art-card"><ScanFace/><div><strong>Check-in facial</strong><span>Reconhecimento rápido e seguro.</span></div></div></div><div className="auth-panel"><div className="auth-form"><div className="mobile-brand brand"><b>MG</b><span>MultiGym<small>Sistema para academias</small></span></div><h2>{mode==='login'?'Entrar no MultiGym':'Criar academia'}</h2><p>{mode==='login'?'Acesse o painel da sua academia.':'Comece a operar sua academia em minutos.'}</p><form onSubmit={submit}>{mode==='register'&&<><Field label="Nome da academia"><input required value={b.gymName||''} onChange={e=>setB({...b,gymName:e.target.value})}/></Field><Field label="Seu nome"><input required value={b.name||''} onChange={e=>setB({...b,name:e.target.value})}/></Field></>}<Field label="E-mail"><input type="email" required value={b.email||''} onChange={e=>setB({...b,email:e.target.value})}/></Field><Field label="Senha"><input type="password" required minLength={8} value={b.password||''} onChange={e=>setB({...b,password:e.target.value})}/></Field>{err&&<div className="error-box">{err}</div>}<Button type="submit" disabled={busy}>{busy?'Processando…':mode==='login'?'Entrar':'Criar minha academia'}</Button></form><button className="link-btn" onClick={()=>{setMode(mode==='login'?'register':'login');setErr('')}}>{mode==='login'?'Ainda não tenho uma academia':'Já tenho uma conta'}</button></div></div></div>}

const menu:[Page,string,React.ComponentType<any>][]=[['dashboard','Dashboard',LayoutDashboard],['students','Alunos',Users],['enrollments','Matrículas',ClipboardList],['workouts','Treinos',Dumbbell],['finance','Financeiro',WalletCards],['products','Produtos',Package],['services','Serviços',BriefcaseBusiness],['sales','Vendas',ReceiptText],['cash','Caixa',ReceiptText],['checkin','Check-in facial',ScanFace],['agenda','Agenda',CalendarDays],['reports','Relatórios',BarChart3],['team','Equipe',UserPlus],['settings','Configurações',Settings]];
function Shell({user,page,setPage,children,onLogout}:{user:User;page:Page;setPage:(p:Page)=>void;children:React.ReactNode;onLogout:()=>void}){const [open,setOpen]=useState(false); return <div className="app-shell"><aside className={open?'sidebar open':'sidebar'}><div className="side-brand"><div className="brand"><b>MG</b><span>MultiGym<small>Sistema para academias</small></span></div><button className="mobile-close" onClick={()=>setOpen(false)}><X/></button></div><nav>{menu.map(([id,label,Icon])=><button key={id} className={page===id?'active':''} onClick={()=>{setPage(id);setOpen(false)}}><Icon size={19}/><span>{label}</span>{id==='checkin'&&<em>Novo</em>}</button>)}</nav><div className="side-plan"><small>PLANO ATUAL</small><strong>Profissional</strong><span>MultiGym 2.0</span><button>Gerenciar plano</button></div><div className="side-user"><div className="avatar">{initial(user.name)}</div><div><strong>{user.name}</strong><span>{user.role}</span></div><MoreHorizontal/></div><button className="logout" onClick={onLogout}><LogOut/> Sair</button></aside><main className="main"><header className="topbar"><button className="mobile-menu icon-btn" onClick={()=>setOpen(true)}><Menu/></button><div><h1>{menu.find(x=>x[0]===page)?.[1]}</h1><span>{user.gym_name}</span></div><div className="top-actions"><button className="icon-btn"><Bell/><i>3</i></button><div className="gym-pill"><Dumbbell size={17}/>{user.gym_name}<ChevronRight size={15}/></div></div></header><section className="content">{children}</section></main></div>}

function Dashboard({go}:{go:(p:Page)=>void}){const [d,setD]=useState<any>(null); useEffect(()=>{get('/dashboard').then(setD)},[]); if(!d)return <Loading/>; const k=d.kpi||{}; return <><div className="page-head"><div><h2>Visão geral</h2><p>O que está acontecendo na sua academia hoje.</p></div><div className="head-actions"><Button onClick={()=>go('students')}><Plus size={17}/> Novo aluno</Button><Button kind="secondary" onClick={()=>go('checkin')}><ScanFace size={17}/> Abrir check-in</Button></div></div><div className="stats"><Stat title="Alunos ativos" value={k.active_students||0} trend="+8 este mês" icon={<Users/>}/><Stat title="Matrículas vencendo" value={k.expiring||0} trend="Próximos 7 dias" icon={<ClipboardList/>} warn/><Stat title="Matrículas vencidas" value={k.expired||0} trend="Atenção necessária" icon={<AlertTriangle/>} danger/><Stat title="Faturamento do mês" value={money(k.revenue)} trend="Recebimentos confirmados" icon={<ArrowUpRight/>}/></div><div className="grid-3"><div className="card finance-chart"><CardTitle title="Resumo financeiro" link="Financeiro" onClick={()=>go('finance')}/><div className="finance-row"><div><small>Receitas</small><strong>{money(d.finance?.revenue)}</strong></div><div><small>Recebidos</small><strong>{money(d.finance?.received)}</strong></div><div><small>Pendentes</small><strong className="danger-text">{money(d.finance?.pending)}</strong></div></div><div className="fake-chart"><div className="chart-line"></div><div className="chart-labels"><span>01</span><span>08</span><span>15</span><span>22</span><span>31</span></div></div></div><div className="card presence"><CardTitle title="Alunos presentes hoje"/><div className="donut"><div><strong>{d.presence?.present||0}</strong><span>presentes</span></div></div><small>{k.active_students?Math.round((Number(d.presence?.present||0)/Number(k.active_students))*100):0}% dos alunos ativos</small></div><div className="card"><CardTitle title="Agenda de hoje" link="Ver agenda" onClick={()=>go('agenda')}/><div className="agenda-list">{(d.appointments||[]).slice(0,5).map((a:any)=><div className="agenda-item" key={a.id}><time>{time(a.starts_at)}</time><div><strong>{a.title}</strong><span>{a.student_name||'Sem aluno'}</span></div><em>{a.type}</em></div>)}{!d.appointments?.length&&<p className="muted">Nenhum compromisso hoje.</p>}</div><Button onClick={()=>go('agenda')} kind="soft"><Plus/> Novo agendamento</Button></div></div><div className="quick card"><CardTitle title="Ações rápidas"/><div className="quick-grid"><Quick label="Novo aluno" icon={<UserPlus/>} onClick={()=>go('students')}/><Quick label="Nova matrícula" icon={<ClipboardList/>} onClick={()=>go('enrollments')}/><Quick label="Novo treino" icon={<Dumbbell/>} onClick={()=>go('workouts')}/><Quick label="Receber pagamento" icon={<WalletCards/>} onClick={()=>go('finance')}/><Quick label="Abrir caixa" icon={<ReceiptText/>} onClick={()=>go('cash')}/></div></div><div className="grid-3 lower"><TableCard title="Matrículas próximas" action="Ver todas" onClick={()=>go('enrollments')}><table><thead><tr><th>Aluno</th><th>Plano</th><th>Vencimento</th><th>Status</th></tr></thead><tbody>{(d.renewals||[]).map((r:any)=><tr key={r.id}><td><div className="person"><span className="avatar sm">{initial(r.full_name)}</span>{r.full_name}</div></td><td>{r.plan_name}</td><td>{date(r.ends_on)}</td><td><Badge tone={new Date(r.ends_on).getTime()-Date.now()<4*864e5?'warn':'good'}>{new Date(r.ends_on).getTime()-Date.now()<4*864e5?'Vencendo':'Normal'}</Badge></td></tr>)}</tbody></table></TableCard><TableCard title="Novos alunos" action="Ver todos" onClick={()=>go('students')}><div className="mini-list">{(d.recentStudents||[]).map((s:any)=><div key={s.id}><span className="avatar sm">{initial(s.full_name)}</span><div><strong>{s.full_name}</strong><small>{s.phone||'Sem telefone'}</small></div><Badge tone="good">Novo</Badge></div>)}</div></TableCard><TableCard title="Treinos ativos" action="Ver todos" onClick={()=>go('workouts')}><div className="mini-list">{(d.workouts||[]).map((w:any)=><div key={w.id}><span className="icon-box"><Dumbbell/></span><div><strong>{w.name}</strong><small>{w.full_name}</small></div><Badge>A</Badge></div>)}</div></TableCard></div></>}
function Stat({title,value,trend,icon,warn,danger}:{title:string;value:any;trend:string;icon:React.ReactNode;warn?:boolean;danger?:boolean}){return <div className="stat card"><div className={`stat-icon ${warn?'warn':''} ${danger?'danger':''}`}>{icon}</div><div><span>{title}</span><strong>{value}</strong><small className={danger?'danger-text':''}>{trend}</small></div></div>}
function CardTitle({title,link,onClick}:{title:string;link?:string;onClick?:()=>void}){return <div className="card-title"><h3>{title}</h3>{link&&<button onClick={onClick}>{link}<ChevronRight/></button>}</div>}
function Quick({label,icon,onClick}:{label:string;icon:React.ReactNode;onClick:()=>void}){return <button className="quick-btn" onClick={onClick}>{icon}<span>{label}</span></button>}
function TableCard({title,action,onClick,children}:{title:string;action?:string;onClick?:()=>void;children:React.ReactNode}){return <div className="card table-card"><CardTitle title={title} link={action} onClick={onClick}/>{children}</div>}
function Badge({children,tone='neutral'}:{children:React.ReactNode;tone?:string}){return <span className={`badge ${tone}`}>{children}</span>}
function Loading(){return <div className="loading"><RefreshCw className="spin"/><span>Carregando…</span></div>}

function Students({onOpen}:{onOpen:(id:string)=>void}){const [items,setItems]=useState<any[]>([]),[search,setSearch]=useState(''),[modal,setModal]=useState(false),[b,setB]=useState<any>({training_level:'beginner'}),[toast,setToast]=useState(''); const load=()=>get('/students?search='+encodeURIComponent(search)).then(setItems); useEffect(()=>{load()},[search]); const save=async(e:React.FormEvent)=>{e.preventDefault();try{await post('/students',{...b,training_experience_months:Number(b.training_experience_months||0),weekly_frequency:b.weekly_frequency?Number(b.weekly_frequency):null,session_duration:b.session_duration?Number(b.session_duration):null});setModal(false);setB({training_level:'beginner'});setToast('Aluno cadastrado com sucesso');load()}catch(e:any){alert(e.message)}}; return <><div className="page-head"><div><h2>Alunos</h2><p>Gerencie cadastro, matrícula, frequência, financeiro e evolução.</p></div><Button onClick={()=>setModal(true)}><Plus/> Novo aluno</Button></div><div className="toolbar"><div className="search"><Search/><input placeholder="Buscar por nome, CPF ou telefone…" value={search} onChange={e=>setSearch(e.target.value)}/></div><Button kind="secondary"><MoreHorizontal/> Filtros</Button></div><div className="card table-card"><table><thead><tr><th>Aluno</th><th>Plano atual</th><th>Vencimento</th><th>Frequência</th><th>Status</th><th></th></tr></thead><tbody>{items.map(s=><tr key={s.id} onClick={()=>onOpen(s.id)} className="click-row"><td><div className="person"><span className="avatar">{initial(s.full_name)}</span><div><strong>{s.full_name}</strong><small>{s.phone||s.email||'Sem contato'}</small></div></div></td><td>{s.plan_name||'Sem matrícula'}</td><td>{date(s.ends_on)}</td><td>{s.ends_on?'—':'—'}</td><td><Badge tone={s.status==='active'?'good':'neutral'}>{s.status==='active'?'Ativo':'Inativo'}</Badge></td><td><ChevronRight/></td></tr>)}</tbody></table>{!items.length&&<Empty title="Nenhum aluno encontrado" desc="Cadastre o primeiro aluno para começar." action={<Button onClick={()=>setModal(true)}><Plus/> Cadastrar aluno</Button>}/>}</div>{modal&&<Modal title="Novo aluno" onClose={()=>setModal(false)} wide><form className="form-grid" onSubmit={save}><Field label="Nome completo"><input required value={b.full_name||''} onChange={e=>setB({...b,full_name:e.target.value})}/></Field><Field label="CPF"><input value={b.cpf||''} onChange={e=>setB({...b,cpf:e.target.value})}/></Field><Field label="Nascimento"><input type="date" value={b.birth_date||''} onChange={e=>setB({...b,birth_date:e.target.value})}/></Field><Field label="Telefone"><input value={b.phone||''} onChange={e=>setB({...b,phone:e.target.value})}/></Field><Field label="E-mail"><input type="email" value={b.email||''} onChange={e=>setB({...b,email:e.target.value})}/></Field><Field label="Nível"><select value={b.training_level} onChange={e=>setB({...b,training_level:e.target.value})}><option value="beginner">Iniciante</option><option value="intermediate">Intermediário</option><option value="advanced">Avançado</option></select></Field><Field label="Experiência (meses)"><input type="number" min="0" value={b.training_experience_months||0} onChange={e=>setB({...b,training_experience_months:e.target.value})}/></Field><Field label="Objetivo"><select value={b.primary_goal||''} onChange={e=>setB({...b,primary_goal:e.target.value})}><option value="">Selecione</option><option>Emagrecimento</option><option>Hipertrofia</option><option>Força</option><option>Condicionamento</option><option>Manutenção</option><option>Performance</option></select></Field><Field label="Frequência semanal"><input type="number" min="1" max="7" value={b.weekly_frequency||''} onChange={e=>setB({...b,weekly_frequency:e.target.value})}/></Field><Field label="Duração do treino (min)"><input type="number" min="15" value={b.session_duration||''} onChange={e=>setB({...b,session_duration:e.target.value})}/></Field><Field label="Limitações / cuidados"><textarea value={b.limitations||''} onChange={e=>setB({...b,limitations:e.target.value})}/></Field><Field label="Preferências"><textarea value={b.preferences||''} onChange={e=>setB({...b,preferences:e.target.value})}/></Field><div className="modal-actions"><Button kind="secondary" onClick={()=>setModal(false)}>Cancelar</Button><Button type="submit">Cadastrar aluno</Button></div></form></Modal>}{toast&&<Toast msg={toast} onClose={()=>setToast('')}/>}</>}

function StudentDetail({id,onBack}:{id:string;onBack:()=>void}){const [d,setD]=useState<any>(null),[tab,setTab]=useState('overview'),[face,setFace]=useState(false),[assessment,setAssessment]=useState(false),[toast,setToast]=useState(''); const load=()=>get('/students/'+id).then(setD); useEffect(()=>{load()},[id]); if(!d)return <Loading/>; const s=d.student; return <><button className="back-link" onClick={onBack}>← Voltar para alunos</button><div className="profile-head card"><div className="profile-avatar">{initial(s.full_name)}</div><div className="profile-main"><div className="profile-name"><div><h2>{s.full_name}</h2><p>{s.email||'Sem e-mail'} · {s.phone||'Sem telefone'}</p></div><Badge tone={s.status==='active'?'good':'neutral'}>{s.status==='active'?'Ativo':'Inativo'}</Badge></div><div className="profile-meta"><span>CPF <b>{s.cpf||'—'}</b></span><span>Nascimento <b>{date(s.birth_date)}</b></span><span>Objetivo <b>{s.primary_goal||'Não informado'}</b></span><span>Experiência <b>{Math.floor(Number(s.training_experience_months||0)/12)} anos</b></span></div></div><div className="profile-actions"><Button kind="secondary" onClick={()=>setAssessment(true)}>+ Avaliação</Button><Button onClick={()=>setFace(true)}><ScanFace/> {d.faceEnrolled?'Atualizar rosto':'Cadastrar rosto'}</Button>{d.faceEnrolled&&<Button kind="secondary" onClick={async()=>{if(confirm('Revogar o reconhecimento facial deste aluno?')){await del('/face/enroll/'+id);load();setToast('Reconhecimento facial revogado')}}}><Trash2/> Revogar biometria</Button>}</div></div><div className="tabs">{[['overview','Visão geral'],['enrollments','Matrículas'],['finance','Financeiro'],['checkins','Check-ins'],['workouts','Treinos'],['assessments','Avaliações'],['history','Histórico']].map(([k,l])=><button className={tab===k?'active':''} onClick={()=>setTab(k)} key={k}>{l}</button>)}</div>{tab==='overview'&&<div className="profile-grid"><div className="card"><CardTitle title="Resumo"/><div className="profile-stats"><div><span>Matrícula</span><strong>{d.enrollments?.[0]?.plan_name||'Sem plano'}</strong><small>{d.enrollments?.[0]?`até ${date(d.enrollments[0].ends_on)}`:'—'}</small></div><div><span>Check-ins</span><strong>{d.checkins?.length||0}</strong><small>últimos registros</small></div><div><span>Pagamentos</span><strong>{money((d.payments||[]).filter((x:any)=>x.status==='paid').reduce((a:any,x:any)=>a+Number(x.amount),0))}</strong><small>histórico carregado</small></div><div><span>Treinos</span><strong>{d.workouts?.filter((x:any)=>x.status==='active').length||0}</strong><small>ativos</small></div></div></div><div className="card"><CardTitle title="Dados de treino"/><div className="detail-list"><span>Nível <b>{s.training_level}</b></span><span>Frequência <b>{s.weekly_frequency||'—'}x/semana</b></span><span>Duração <b>{s.session_duration||'—'} min</b></span><span>Cuidados <b>{s.limitations||'Nenhum informado'}</b></span></div></div><div className="card"><CardTitle title="Últimos check-ins"/><div className="timeline">{(d.checkins||[]).slice(0,6).map((c:any)=><div key={c.id}><i><Clock3/></i><div><strong>{date(c.checked_at)} às {time(c.checked_at)}</strong><span>Entrada por {c.method==='face'?'reconhecimento facial':'atendimento'}</span></div></div>)}</div></div><div className="card"><CardTitle title="Últimos pagamentos"/><div className="mini-list">{(d.payments||[]).slice(0,5).map((p:any)=><div key={p.id}><span className="icon-box"><WalletCards/></span><div><strong>{money(p.amount)}</strong><small>{date(p.paid_at||p.created_at)} · {p.method}</small></div><Badge tone={p.status==='paid'?'good':'warn'}>{p.status}</Badge></div>)}</div></div></div>}{tab==='enrollments'&&<SimpleTable rows={d.enrollments} cols={['plan_name','starts_on','ends_on','amount','status']} labels={['Plano','Início','Vencimento','Valor','Status']}/>} {tab==='finance'&&<SimpleTable rows={d.payments} cols={['amount','paid_at','due_at','method','status']} labels={['Valor','Pago em','Vencimento','Método','Status']} moneyCols={['amount']}/>} {tab==='checkins'&&<SimpleTable rows={d.checkins} cols={['checked_at','method','confidence']} labels={['Data','Método','Confiança']}/>} {tab==='workouts'&&<div className="workout-grid">{d.workouts?.map((w:any)=><div className="card workout-card" key={w.id}><div className="workout-title"><span className="icon-box"><Dumbbell/></span><div><h3>{w.name}</h3><p>{w.objective||'Objetivo não informado'}</p></div></div><div className="exercise-list">{(w.exercises||[]).map((e:any)=><div key={e.id}><strong>{e.exercise}</strong><span>{e.sets||'—'} séries × {e.reps||'—'} · {e.load||'peso livre'}</span></div>)}</div></div>)}</div>} {tab==='assessments'&&<SimpleTable rows={d.assessments} cols={['measured_at','weight','body_fat','muscle_mass','waist','notes']} labels={['Data','Peso','Gordura','Massa muscular','Cintura','Observações']}/>} {tab==='history'&&<div className="card"><Empty title="Histórico operacional" desc="O histórico de auditoria da academia fica disponível no módulo de gestão e será expandido conforme novas ações forem registradas."/></div>}{face&&<FaceEnrollment studentId={id} onClose={()=>setFace(false)} onDone={()=>{setFace(false);setToast('Reconhecimento facial atualizado');load()}}/>}{assessment&&<Assessment studentId={id} onClose={()=>setAssessment(false)} onDone={()=>{setAssessment(false);setToast('Avaliação registrada');load()}}/>}{toast&&<Toast msg={toast} onClose={()=>setToast('')}/>}</>}
function SimpleTable({rows=[],cols,labels,moneyCols=[]}:{rows:any[];cols:string[];labels:string[];moneyCols?:string[]}){return <div className="card table-card"><table><thead><tr>{labels.map(l=><th key={l}>{l}</th>)}</tr></thead><tbody>{rows.map((r:any,i)=><tr key={r.id||i}>{cols.map(c=><td key={c}>{moneyCols.includes(c)?money(r[c]):c.includes('date')||c.endsWith('_at')||c.endsWith('_on')?date(r[c]):c==='status'?<Badge tone={r[c]==='paid'||r[c]==='active'?'good':'warn'}>{r[c]}</Badge>:r[c]??'—'}</td>)}</tr>)}</tbody></table>{!rows.length&&<p className="muted center">Nenhum registro.</p>}</div>}

function FaceEnrollment({studentId,onClose,onDone}:{studentId:string;onClose:()=>void;onDone:()=>void}){return <Modal title="Cadastrar reconhecimento facial" onClose={onClose}><FaceCapture mode="enroll" studentId={studentId} onDone={onDone}/></Modal>}
function FaceCapture({mode,studentId,onDone}:{mode:'enroll'|'checkin';studentId?:string;onDone?:()=>void}){const video=useRef<HTMLVideoElement>(null); const [ready,setReady]=useState(false),[status,setStatus]=useState('Carregando reconhecimento facial…'),[consent,setConsent]=useState(false),[busy,setBusy]=useState(false); const stream=useRef<MediaStream|null>(null);
 useEffect(()=>{let alive=true;(async()=>{try{await Promise.all([faceapi.nets.tinyFaceDetector.loadFromUri('/models'),faceapi.nets.faceLandmark68Net.loadFromUri('/models'),faceapi.nets.faceRecognitionNet.loadFromUri('/models')]);if(!alive)return;const s=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:480}},audio:false});stream.current=s;if(video.current){video.current.srcObject=s;await video.current.play();}setReady(true);setStatus('Posicione o rosto no centro da câmera.')}catch(e){setStatus('Não foi possível iniciar a câmera/modelos. Verifique permissão e execute o download dos modelos.')}})();return()=>{stream.current?.getTracks().forEach(t=>t.stop())}},[]);
 const capture=async()=>{if(!video.current||!ready||busy)return;setBusy(true);try{const r=await faceapi.detectSingleFace(video.current,new faceapi.TinyFaceDetectorOptions({inputSize:320,scoreThreshold:.55})).withFaceLandmarks().withFaceDescriptor();if(!r){setStatus('Não encontrei um rosto. Ajuste a iluminação e tente novamente.');return;} const descriptor=Array.from(r.descriptor); if(mode==='enroll'){if(!consent){setStatus('Confirme o consentimento para armazenar o template biométrico.');return;} await post('/face/enroll',{student_id:studentId,descriptor,consent:true});setStatus('Rosto cadastrado com sucesso.');onDone?.()} }catch(e:any){setStatus(e.message)}finally{setBusy(false)}};
 return <div className="face-capture"><div className="camera"><video ref={video} muted playsInline/><div className="face-guide"></div><div className="camera-status">{ready?<><CheckCircle2/> Câmera pronta</>:<RefreshCw className="spin"/>}{status}</div></div>{mode==='enroll'&&<label className="consent"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/><span>Autorizo o uso do meu template biométrico facial exclusivamente para identificação e check-in nesta academia, podendo revogar a autorização.</span></label>}<Button onClick={capture} disabled={!ready||busy}>{busy?'Processando…':'Capturar e cadastrar'}</Button><p className="privacy-note"><ShieldCheck/> O sistema armazena o template facial protegido, não uma foto de rosto.</p></div>}

function Assessment({studentId,onClose,onDone}:{studentId:string;onClose:()=>void;onDone:()=>void}){const [b,setB]=useState<any>({}); const save=async(e:React.FormEvent)=>{e.preventDefault();try{await post('/assessments',{...b,student_id:studentId});onDone()}catch(e:any){alert(e.message)}};return <Modal title="Nova avaliação física" onClose={onClose}><form className="form-grid" onSubmit={save}>{[['weight','Peso (kg)'],['height','Altura (cm)'],['body_fat','Gordura (%)'],['muscle_mass','Massa muscular (kg)'],['arm','Braço (cm)'],['chest','Peito (cm)'],['waist','Cintura (cm)'],['abdomen','Abdômen (cm)'],['hip','Quadril (cm)'],['thigh','Coxa (cm)'],['calf','Panturrilha (cm)']].map(([k,l])=><Field label={l} key={k}><input type="number" step="0.01" value={b[k]||''} onChange={e=>setB({...b,[k]:e.target.value})}/></Field>)}<Field label="Observações"><textarea value={b.notes||''} onChange={e=>setB({...b,notes:e.target.value})}/></Field><div className="modal-actions"><Button kind="secondary" onClick={onClose}>Cancelar</Button><Button type="submit">Salvar avaliação</Button></div></form></Modal>}

function Plans(){return <CrudPage title="Planos" desc="Planos e preços oferecidos pela academia." endpoint="/plans" fields={[['name','Nome'],['price','Preço'],['duration_days','Duração em dias'],['description','Descrição'],['status','Status']]}/>}
function Products(){return <CrudPage title="Produtos" desc="Venda de produtos e controle de estoque." endpoint="/products" fields={[['name','Nome'],['sku','SKU'],['category','Categoria'],['cost','Custo'],['price','Preço de venda'],['stock','Estoque'],['min_stock','Estoque mínimo'],['active','Ativo']]}/>}
function Services(){return <CrudPage title="Serviços" desc="Serviços, avaliações, personal e aulas comercializados." endpoint="/services" fields={[['name','Nome'],['description','Descrição'],['price','Preço'],['duration_minutes','Duração (min)'],['active','Ativo']]}/>}
function CrudPage({title,desc,endpoint,fields}:{title:string;desc:string;endpoint:string;fields:[string,string][]}){const [items,setItems]=useState<any[]>([]),[modal,setModal]=useState(false),[b,setB]=useState<any>({active:true,status:'active'});const load=()=>get(endpoint).then(setItems);useEffect(()=>{load()},[]);const save=async(e:React.FormEvent)=>{e.preventDefault();try{await post(endpoint,{...b,price:b.price?Number(b.price):undefined,duration_days:b.duration_days?Number(b.duration_days):undefined,duration_minutes:b.duration_minutes?Number(b.duration_minutes):undefined,cost:b.cost?Number(b.cost):undefined,stock:b.stock?Number(b.stock):0,min_stock:b.min_stock?Number(b.min_stock):0});setModal(false);setB({active:true,status:'active'});load()}catch(e:any){alert(e.message)}};return <><div className="page-head"><div><h2>{title}</h2><p>{desc}</p></div><Button onClick={()=>setModal(true)}><Plus/> Novo</Button></div><div className="card table-card"><table><thead><tr>{fields.slice(0,6).map(([,l])=><th key={l}>{l}</th>)}</tr></thead><tbody>{items.map(x=><tr key={x.id}>{fields.slice(0,6).map(([k])=><td key={k}>{['price','cost'].includes(k)?money(x[k]):k==='active'?<Badge tone={x[k]?'good':'neutral'}>{x[k]?'Ativo':'Inativo'}</Badge>:x[k]??'—'}</td>)}</tr>)}</tbody></table>{!items.length&&<Empty title="Nenhum registro" desc="Cadastre o primeiro item para começar." action={<Button onClick={()=>setModal(true)}><Plus/> Novo</Button>}/>}</div>{modal&&<Modal title={`Novo ${title.slice(0,-1).toLowerCase()}`} onClose={()=>setModal(false)}><form className="form-grid" onSubmit={save}>{fields.map(([k,l])=><Field label={l} key={k}>{k==='description'?<textarea value={b[k]||''} onChange={e=>setB({...b,[k]:e.target.value})}/>:k==='status'?<select value={b[k]||'active'} onChange={e=>setB({...b,[k]:e.target.value})}><option value="active">Ativo</option><option value="inactive">Inativo</option></select>:k==='active'?<select value={String(b[k]??true)} onChange={e=>setB({...b,[k]:e.target.value==='true'})}><option value="true">Ativo</option><option value="false">Inativo</option></select>:<input required={k==='name'} type={['price','cost','stock','min_stock','duration_days','duration_minutes'].includes(k)?'number':'text'} step="0.01" value={b[k]??''} onChange={e=>setB({...b,[k]:e.target.value})}/>}</Field>)}<div className="modal-actions"><Button kind="secondary" onClick={()=>setModal(false)}>Cancelar</Button><Button type="submit">Salvar</Button></div></form></Modal>}</>}

function Enrollments(){const [rows,setRows]=useState<any[]>([]),[plans,setPlans]=useState<any[]>([]),[students,setStudents]=useState<any[]>([]),[modal,setModal]=useState(false),[b,setB]=useState<any>({});const load=()=>get('/enrollments').then(setRows);useEffect(()=>{load();get('/plans').then(setPlans);get('/students').then(setStudents)},[]);const save=async(e:React.FormEvent)=>{e.preventDefault();try{await post('/enrollments',{...b,amount:b.amount?Number(b.amount):undefined});setModal(false);setB({});load()}catch(e:any){alert(e.message)}};return <><div className="page-head"><div><h2>Matrículas</h2><p>Controle de planos, vencimentos e renovações.</p></div><Button onClick={()=>setModal(true)}><Plus/> Nova matrícula</Button></div><div className="card table-card"><table><thead><tr><th>Aluno</th><th>Plano</th><th>Início</th><th>Vencimento</th><th>Valor</th><th>Status</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{r.student_name}</td><td>{r.plan_name}</td><td>{date(r.starts_on)}</td><td>{date(r.ends_on)}</td><td>{money(r.amount)}</td><td><Badge tone={r.status==='active'?'good':'warn'}>{r.status}</Badge></td></tr>)}</tbody></table></div>{modal&&<Modal title="Nova matrícula" onClose={()=>setModal(false)}><form className="form-grid" onSubmit={save}><Field label="Aluno"><select required value={b.student_id||''} onChange={e=>setB({...b,student_id:e.target.value})}><option value="">Selecione</option>{students.map(s=><option key={s.id} value={s.id}>{s.full_name}</option>)}</select></Field><Field label="Plano"><select required value={b.plan_id||''} onChange={e=>{const p=plans.find(x=>x.id===e.target.value);setB({...b,plan_id:e.target.value,amount:p?.price})}}><option value="">Selecione</option>{plans.map(p=><option key={p.id} value={p.id}>{p.name} — {money(p.price)}</option>)}</select></Field><Field label="Início"><input type="date" required value={b.starts_on||''} onChange={e=>setB({...b,starts_on:e.target.value})}/></Field><Field label="Valor"><input type="number" step="0.01" value={b.amount||''} onChange={e=>setB({...b,amount:e.target.value})}/></Field><Field label="Pagamento"><select value={b.method||'pix'} onChange={e=>setB({...b,method:e.target.value})}><option value="pix">Pix</option><option value="cash">Dinheiro</option><option value="card">Cartão</option><option value="transfer">Transferência</option></select></Field><div className="modal-actions"><Button kind="secondary" onClick={()=>setModal(false)}>Cancelar</Button><Button type="submit">Criar matrícula</Button></div></form></Modal>}</>}

function Finance(){const [rows,setRows]=useState<any[]>([]),[students,setStudents]=useState<any[]>([]),[modal,setModal]=useState(false),[b,setB]=useState<any>({status:'paid',method:'pix'});const load=()=>get('/payments').then(setRows);useEffect(()=>{load();get('/students').then(setStudents)},[]);const total=rows.filter(r=>r.status==='paid').reduce((a,r)=>a+Number(r.amount),0),pending=rows.filter(r=>r.status==='pending').reduce((a,r)=>a+Number(r.amount),0);const save=async(e:React.FormEvent)=>{e.preventDefault();try{await post('/payments',{...b,amount:Number(b.amount)});setModal(false);setB({status:'paid',method:'pix'});load()}catch(e:any){alert(e.message)}};return <><div className="page-head"><div><h2>Financeiro</h2><p>Recebimentos, pendências, vendas e visão financeira da academia.</p></div><Button onClick={()=>setModal(true)}><Plus/> Registrar pagamento</Button></div><div className="stats"><Stat title="Recebido" value={money(total)} trend="Pagamentos confirmados" icon={<ArrowUpRight/>}/><Stat title="A receber" value={money(pending)} trend="Pendências abertas" icon={<Clock3/>} warn/><Stat title="Transações" value={rows.length} trend="Últimos registros" icon={<WalletCards/>}/><Stat title="Ticket médio" value={money(rows.length?total/rows.filter(r=>r.status==='paid').length:0)} trend="Por pagamento" icon={<BarChart3/>}/></div><div className="card table-card"><CardTitle title="Últimas movimentações"/><table><thead><tr><th>Aluno</th><th>Categoria</th><th>Valor</th><th>Método</th><th>Data</th><th>Status</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{r.student_name}</td><td>{r.category}</td><td>{money(r.amount)}</td><td>{r.method}</td><td>{date(r.paid_at||r.created_at)}</td><td><Badge tone={r.status==='paid'?'good':'warn'}>{r.status}</Badge></td></tr>)}</tbody></table></div>{modal&&<Modal title="Registrar pagamento" onClose={()=>setModal(false)}><form className="form-grid" onSubmit={save}><Field label="Aluno"><select required value={b.student_id||''} onChange={e=>setB({...b,student_id:e.target.value})}><option value="">Selecione</option>{students.map(s=><option key={s.id} value={s.id}>{s.full_name}</option>)}</select></Field><Field label="Valor"><input required type="number" step="0.01" value={b.amount||''} onChange={e=>setB({...b,amount:e.target.value})}/></Field><Field label="Método"><select value={b.method} onChange={e=>setB({...b,method:e.target.value})}><option value="pix">Pix</option><option value="cash">Dinheiro</option><option value="card">Cartão</option><option value="transfer">Transferência</option><option value="other">Outro</option></select></Field><Field label="Status"><select value={b.status} onChange={e=>setB({...b,status:e.target.value})}><option value="paid">Pago</option><option value="pending">Pendente</option></select></Field><Field label="Observação"><textarea value={b.notes||''} onChange={e=>setB({...b,notes:e.target.value})}/></Field><div className="modal-actions"><Button kind="secondary" onClick={()=>setModal(false)}>Cancelar</Button><Button type="submit">Registrar</Button></div></form></Modal>}</>}


function Sales(){const [products,setProducts]=useState<any[]>([]),[services,setServices]=useState<any[]>([]),[students,setStudents]=useState<any[]>([]),[items,setItems]=useState<any[]>([]),[student,setStudent]=useState(''),[method,setMethod]=useState('pix'),[history,setHistory]=useState<any[]>([]);const load=()=>{get('/products').then(setProducts);get('/services').then(setServices);get('/students').then(setStudents);get('/sales').then(setHistory)};useEffect(()=>{load()},[]);const add=(x:any,type:'product'|'service')=>setItems([...items,{[type==='product'?'product_id':'service_id']:x.id,description:x.name,quantity:1,unit_price:Number(x.price)}]);const total=items.reduce((a,x)=>a+Number(x.quantity)*Number(x.unit_price),0);const checkout=async()=>{if(!items.length)return;try{await post('/sales',{student_id:student||null,method,items});setItems([]);alert('Venda concluída');load()}catch(e:any){alert(e.message)}};return <><div className="page-head"><div><h2>Vendas</h2><p>PDV rápido para produtos e serviços da academia.</p></div><Button onClick={checkout} disabled={!items.length}><ReceiptText/> Finalizar venda · {money(total)}</Button></div><div className="sales-grid"><div className="card product-picker"><CardTitle title="Produtos"/><div className="picker-grid">{products.map(x=><button key={x.id} onClick={()=>add(x,'product')} disabled={Number(x.stock)<=0}><span className="icon-box"><Package/></span><div><strong>{x.name}</strong><small>{money(x.price)} · estoque {x.stock}</small></div></button>)}</div><CardTitle title="Serviços"/><div className="picker-grid">{services.map(x=><button key={x.id} onClick={()=>add(x,'service')}><span className="icon-box"><BriefcaseBusiness/></span><div><strong>{x.name}</strong><small>{money(x.price)}</small></div></button>)}</div></div><div className="card sale-cart"><CardTitle title="Carrinho"/><Field label="Aluno (opcional)"><select value={student} onChange={e=>setStudent(e.target.value)}><option value="">Consumidor não identificado</option>{students.map(s=><option key={s.id} value={s.id}>{s.full_name}</option>)}</select></Field><Field label="Pagamento"><select value={method} onChange={e=>setMethod(e.target.value)}><option value="pix">Pix</option><option value="cash">Dinheiro</option><option value="card">Cartão</option><option value="transfer">Transferência</option></select></Field><div className="cart-items">{items.map((x,i)=><div key={i}><div><strong>{x.description}</strong><small>{x.quantity} × {money(x.unit_price)}</small></div><button onClick={()=>setItems(items.filter((_,j)=>j!==i))}><Trash2/></button></div>)}</div><div className="sale-total"><span>Total</span><strong>{money(total)}</strong></div><Button onClick={checkout} disabled={!items.length}>Concluir venda</Button><h4>Últimas vendas</h4>{history.slice(0,5).map(x=><div className="sale-history" key={x.id}><span>{date(x.sold_at)}</span><strong>{money(x.total)}</strong><small>{x.method}</small></div>)}</div></div></>}

function Cash(){const [d,setD]=useState<any>(null),[open,setOpen]=useState(false),[close,setClose]=useState(false),[movement,setMovement]=useState(false),[b,setB]=useState<any>({opening_amount:0,type:'supply',method:'cash'}),[toast,setToast]=useState('');const load=()=>get('/cash/current').then(setD);useEffect(()=>{load()},[]);const openCash=async(e:React.FormEvent)=>{e.preventDefault();try{await post('/cash/open',{opening_amount:Number(b.opening_amount)});setOpen(false);load()}catch(e:any){alert(e.message)}};const closeCash=async(e:React.FormEvent)=>{e.preventDefault();try{const r=await post('/cash/close',{closing_amount:Number(b.closing_amount),notes:b.notes});setClose(false);setToast(`Caixa fechado. Diferença: ${money(r.register.difference)}`);load()}catch(e:any){alert(e.message)}};return <><div className="page-head"><div><h2>Caixa</h2><p>Abertura, movimentações, sangrias, suprimentos e fechamento.</p></div>{d?.register?<div className="head-actions"><Button kind="secondary" onClick={()=>setMovement(true)}><ArrowDownRight/> Sangria / suprimento</Button><Button onClick={()=>setClose(true)}><LockKeyhole/> Fechar caixa</Button></div>:<Button onClick={()=>setOpen(true)}><Plus/> Abrir caixa</Button>}</div>{d?.register?<><div className="cash-hero card"><div><small>CAIXA ABERTO</small><h2>#{d.register.id.slice(0,8).toUpperCase()}</h2><p>Aberto em {date(d.register.opened_at)} às {time(d.register.opened_at)}</p></div><div className="cash-total"><span>Saldo esperado</span><strong>{money(Number(d.register.opening_amount)+(d.movements||[]).reduce((a:any,m:any)=>a+(m.direction==='in'?Number(m.amount):-Number(m.amount)),0))}</strong></div></div><div className="card table-card"><CardTitle title="Movimentações do caixa"/><table><thead><tr><th>Tipo</th><th>Descrição</th><th>Método</th><th>Valor</th><th>Hora</th></tr></thead><tbody>{(d.movements||[]).map((m:any)=><tr key={m.id}><td>{m.type}</td><td>{m.description}</td><td>{m.method}</td><td className={m.direction==='in'?'good-text':'danger-text'}>{m.direction==='in'?'+':'-'} {money(m.amount)}</td><td>{time(m.created_at)}</td></tr>)}</tbody></table></div></>:<div className="card"><Empty title="Nenhum caixa aberto" desc="Abra o caixa para registrar recebimentos, vendas e movimentos do dia." action={<Button onClick={()=>setOpen(true)}><Plus/> Abrir caixa</Button>}/></div>}{open&&<Modal title="Abrir caixa" onClose={()=>setOpen(false)}><form onSubmit={openCash}><Field label="Fundo inicial"><input type="number" step="0.01" value={b.opening_amount} onChange={e=>setB({...b,opening_amount:e.target.value})}/></Field><div className="modal-actions"><Button kind="secondary" onClick={()=>setOpen(false)}>Cancelar</Button><Button type="submit">Abrir caixa</Button></div></form></Modal>}{movement&&<Modal title="Movimentação de caixa" onClose={()=>setMovement(false)}><form onSubmit={async e=>{e.preventDefault();try{await post('/cash/movement',{type:b.type,amount:Number(b.amount),method:b.method,description:b.description});setMovement(false);setB({...b,amount:'',description:''});load()}catch(e:any){alert(e.message)}}}><Field label="Tipo"><select value={b.type} onChange={e=>setB({...b,type:e.target.value})}><option value="supply">Suprimento — entrada</option><option value="withdrawal">Sangria — saída</option></select></Field><Field label="Valor"><input required type="number" step="0.01" value={b.amount||''} onChange={e=>setB({...b,amount:e.target.value})}/></Field><Field label="Método"><select value={b.method} onChange={e=>setB({...b,method:e.target.value})}><option value="cash">Dinheiro</option><option value="pix">Pix</option><option value="card">Cartão</option></select></Field><Field label="Descrição"><input required value={b.description||''} onChange={e=>setB({...b,description:e.target.value})}/></Field><div className="modal-actions"><Button kind="secondary" onClick={()=>setMovement(false)}>Cancelar</Button><Button type="submit">Registrar movimento</Button></div></form></Modal>}{close&&<Modal title="Fechar caixa" onClose={()=>setClose(false)}><form onSubmit={closeCash}><p className="muted">Informe quanto foi contado fisicamente no caixa. O sistema compara com o saldo esperado.</p><Field label="Valor contado"><input required type="number" step="0.01" value={b.closing_amount||''} onChange={e=>setB({...b,closing_amount:e.target.value})}/></Field><Field label="Observações"><textarea value={b.notes||''} onChange={e=>setB({...b,notes:e.target.value})}/></Field><div className="modal-actions"><Button kind="secondary" onClick={()=>setClose(false)}>Cancelar</Button><Button type="submit">Fechar caixa</Button></div></form></Modal>}{toast&&<Toast msg={toast} onClose={()=>setToast('')}/>}</>}

function Checkin(){const [students,setStudents]=useState<any[]>([]),[manual,setManual]=useState(false),[search,setSearch]=useState(''),[msg,setMsg]=useState('');const load=()=>get('/checkins/today').then(setStudents);useEffect(()=>{load()},[]);const manualList=students.filter(s=>s.full_name.toLowerCase().includes(search.toLowerCase()));return <><div className="page-head"><div><h2>Check-in</h2><p>Ponto de entrada com reconhecimento facial ou atendimento manual.</p></div><Button kind="secondary" onClick={()=>setManual(true)}><UserRound/> Check-in manual</Button></div><div className="checkin-grid"><div className="card checkin-machine"><div className="machine-head"><div><small>MULTIGYM CHECK-IN</small><h2>Posicione seu rosto</h2></div><Badge tone="good">● Online</Badge></div><FaceKiosk onSuccess={(text)=>{setMsg(text);load()}}/><p className="privacy-note"><ShieldCheck/> Templates faciais são armazenados de forma protegida e usados somente para identificação nesta academia.</p></div><div className="card"><CardTitle title="Entradas de hoje"/><div className="checkin-count"><strong>{students.length}</strong><span>check-ins realizados</span></div><div className="mini-list">{students.slice(0,9).map(s=><div key={s.id}><span className="avatar sm">{initial(s.full_name)}</span><div><strong>{s.full_name}</strong><small>{time(s.checked_at)} · {s.method==='face'?'Facial':'Manual'}</small></div><Badge tone="good">OK</Badge></div>)}</div>{!students.length&&<p className="muted">Nenhum check-in ainda.</p>}</div></div>{msg&&<Toast msg={msg} onClose={()=>setMsg('')}/>} {manual&&<Modal title="Check-in manual" onClose={()=>setManual(false)}><div className="search"><Search/><input placeholder="Buscar aluno…" value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="manual-list">{manualList.slice(0,10).map(s=><button key={s.id} onClick={async()=>{try{const r=await post('/checkins',{student_id:s.id,method:'manual'});setManual(false);setMsg(r.already?'Este aluno já fez check-in hoje':`Check-in realizado para ${s.full_name}`);load()}catch(e:any){alert(e.message)}}}><span className="avatar">{initial(s.full_name)}</span><span><strong>{s.full_name}</strong><small>{s.phone||'Sem telefone'}</small></span><ChevronRight/></button>)}</div></Modal>}</>}
function FaceKiosk({onSuccess}:{onSuccess:(s:string)=>void}){const video=useRef<HTMLVideoElement>(null);const [status,setStatus]=useState('Inicializando…'),[ready,setReady]=useState(false),stream=useRef<MediaStream|null>(null),busy=useRef(false);useEffect(()=>{let alive=true;(async()=>{try{await Promise.all([faceapi.nets.tinyFaceDetector.loadFromUri('/models'),faceapi.nets.faceLandmark68Net.loadFromUri('/models'),faceapi.nets.faceRecognitionNet.loadFromUri('/models')]);const s=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:800},height:{ideal:600}},audio:false});stream.current=s;if(video.current){video.current.srcObject=s;await video.current.play()}if(alive){setReady(true);setStatus('Aguardando rosto…')}}catch{setStatus('Câmera/modelos indisponíveis. Use o check-in manual.')}})();return()=>stream.current?.getTracks().forEach(t=>t.stop())},[]);useEffect(()=>{if(!ready)return;const timer=setInterval(async()=>{if(busy.current||!video.current)return;busy.current=true;try{const r=await faceapi.detectSingleFace(video.current,new faceapi.TinyFaceDetectorOptions({inputSize:320,scoreThreshold:.55})).withFaceLandmarks().withFaceDescriptor();if(r){setStatus('Identificando…');const m=await post('/face/match',{descriptor:Array.from(r.descriptor),threshold:.52});const c=await post('/checkins',{student_id:m.match.student_id,method:'face',confidence:1-Math.min(1,m.match.distance)});onSuccess(c.already?`${m.match.full_name} já fez check-in hoje`:`Bem-vindo(a), ${m.match.full_name}!`);setStatus('Aguardando próximo rosto…')}}catch{setStatus('Rosto não reconhecido. Tente novamente.')}finally{busy.current=false}},1500);return()=>clearInterval(timer)},[ready]);return <div className="kiosk-camera"><video ref={video} muted playsInline/><div className="kiosk-ring"></div><div className="kiosk-status">{ready?<CheckCircle2/>:<RefreshCw className="spin"/>}{status}</div></div>}

function Workouts(){const [students,setStudents]=useState<any[]>([]),[ex,setEx]=useState<any[]>([]),[student,setStudent]=useState(''),[profile,setProfile]=useState<any>({level:'beginner',goal:'',experience:0,frequency:3,duration:60}),[items,setItems]=useState<any[]>([]),[generated,setGenerated]=useState<any>(null),[busy,setBusy]=useState(false);useEffect(()=>{get('/students').then(setStudents);get('/exercises').then(setEx)},[]);useEffect(()=>{const s=students.find(x=>x.id===student);if(s)setProfile({level:s.training_level,goal:s.primary_goal||'',experience:Number(s.training_experience_months||0),frequency:s.weekly_frequency||3,duration:s.session_duration||60})},[student]);const generate=()=>{setBusy(true);setTimeout(()=>{const muscle=profile.goal==='Força'?'Força':profile.goal==='Emagrecimento'?'Condicionamento':'Hipertrofia';const picks=ex.slice(0,8);setGenerated({name:`Treino ${profile.frequency>=4?'ABC':'AB'} — ${muscle}`,objective:`${profile.goal||'Desenvolvimento geral'} · ${profile.level==='beginner'?'iniciante':profile.level==='intermediate'?'intermediário':'avançado'}`,exercises:picks.map((x,i)=>({exercise_id:x.id,exercise:x.name,sets:profile.level==='beginner'?'3':'4',reps:profile.goal==='Força'?'5–8':'8–12',load:'A definir',rest:profile.goal==='Força'?'120s':'60–90s'}))});setBusy(false)},450)};const save=async()=>{if(!student||!generated)return;try{await post('/workouts',{student_id:student,name:generated.name,objective:generated.objective,starts_on:new Date().toISOString().slice(0,10),review_on:new Date(Date.now()+45*864e5).toISOString().slice(0,10),exercises:generated.exercises});alert('Treino salvo e vinculado ao aluno.')}catch(e:any){alert(e.message)}};return <><div className="page-head"><div><h2>Treinos</h2><p>Prescrição personalizada com base no perfil do aluno.</p></div></div><div className="workout-builder"><div className="card"><CardTitle title="Perfil do aluno"/><Field label="Aluno"><select value={student} onChange={e=>setStudent(e.target.value)}><option value="">Selecione um aluno</option>{students.map(s=><option key={s.id} value={s.id}>{s.full_name}</option>)}</select></Field><div className="profile-questions"><Field label="Nível"><select value={profile.level} onChange={e=>setProfile({...profile,level:e.target.value})}><option value="beginner">Iniciante</option><option value="intermediate">Intermediário</option><option value="advanced">Avançado</option></select></Field><Field label="Objetivo"><select value={profile.goal} onChange={e=>setProfile({...profile,goal:e.target.value})}><option value="">Geral</option><option>Emagrecimento</option><option>Hipertrofia</option><option>Força</option><option>Condicionamento</option><option>Manutenção</option><option>Performance</option></select></Field><Field label="Experiência (meses)"><input type="number" value={profile.experience} onChange={e=>setProfile({...profile,experience:e.target.value})}/></Field><Field label="Frequência semanal"><input type="number" min="2" max="7" value={profile.frequency} onChange={e=>setProfile({...profile,frequency:e.target.value})}/></Field><Field label="Duração (min)"><input type="number" value={profile.duration} onChange={e=>setProfile({...profile,duration:e.target.value})}/></Field></div><Button onClick={generate} disabled={!student||busy}><Dumbbell/> {busy?'Gerando…':'Gerar treino personalizado'}</Button><p className="muted small">A sugestão deve ser revisada e aprovada pelo profissional antes de ser entregue ao aluno.</p></div><div className="card generated"><CardTitle title="Pré-visualização"/>{generated?<><div className="generated-head"><div><h2>{generated.name}</h2><p>{generated.objective}</p></div><Button onClick={save}><CheckCircle2/> Aprovar e salvar</Button></div><div className="exercise-list big">{generated.exercises.map((e:any,i:number)=><div key={i}><div><strong>{i+1}. {e.exercise}</strong><span>{e.sets} séries · {e.reps} repetições · descanso {e.rest}</span></div><Badge>{e.load}</Badge></div>)}</div></>:<Empty title="Nenhum treino gerado" desc="Selecione um aluno e gere uma sugestão personalizada."/>}</div></div></>}

function Agenda(){const [rows,setRows]=useState<any[]>([]),[students,setStudents]=useState<any[]>([]),[modal,setModal]=useState(false),[b,setB]=useState<any>({type:'assessment'});const load=()=>get('/appointments').then(setRows);useEffect(()=>{load();get('/students').then(setStudents)},[]);const save=async(e:React.FormEvent)=>{e.preventDefault();try{await post('/appointments',b);setModal(false);setB({type:'assessment'});load()}catch(e:any){alert(e.message)}};return <><div className="page-head"><div><h2>Agenda</h2><p>Organize avaliações, personal, aulas e compromissos.</p></div><Button onClick={()=>setModal(true)}><Plus/> Novo agendamento</Button></div><div className="card agenda-calendar"><div className="calendar-head"><button>‹</button><strong>{new Date().toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</strong><button>›</button></div><div className="agenda-board">{rows.slice(0,20).map(a=><div className="calendar-event" key={a.id}><time>{date(a.starts_at)} · {time(a.starts_at)}</time><div><strong>{a.title}</strong><span>{a.student_name||'Sem aluno'} · {a.type}</span></div><Badge>{a.status}</Badge></div>)}</div>{!rows.length&&<Empty title="Agenda vazia" desc="Crie o primeiro compromisso."/>}</div>{modal&&<Modal title="Novo agendamento" onClose={()=>setModal(false)}><form className="form-grid" onSubmit={save}><Field label="Título"><input required value={b.title||''} onChange={e=>setB({...b,title:e.target.value})}/></Field><Field label="Aluno"><select value={b.student_id||''} onChange={e=>setB({...b,student_id:e.target.value})}><option value="">Sem aluno</option>{students.map(s=><option key={s.id} value={s.id}>{s.full_name}</option>)}</select></Field><Field label="Tipo"><select value={b.type} onChange={e=>setB({...b,type:e.target.value})}><option value="assessment">Avaliação</option><option value="personal">Personal</option><option value="class">Aula</option><option value="meeting">Reunião</option><option value="other">Outro</option></select></Field><Field label="Início"><input required type="datetime-local" value={b.starts_at||''} onChange={e=>setB({...b,starts_at:e.target.value})}/></Field><Field label="Fim"><input required type="datetime-local" value={b.ends_at||''} onChange={e=>setB({...b,ends_at:e.target.value})}/></Field><Field label="Observação"><textarea value={b.notes||''} onChange={e=>setB({...b,notes:e.target.value})}/></Field><div className="modal-actions"><Button kind="secondary" onClick={()=>setModal(false)}>Cancelar</Button><Button type="submit">Agendar</Button></div></form></Modal>}</>}

function Reports(){const [d,setD]=useState<any>(null);useEffect(()=>{get('/reports/overview').then(setD)},[]);if(!d)return <Loading/>;return <><div className="page-head"><div><h2>Relatórios</h2><p>Indicadores para acompanhar a saúde da operação.</p></div></div><div className="grid-2"><TableCard title="Faturamento por mês"><table><thead><tr><th>Mês</th><th>Receita</th><th>Pendente</th></tr></thead><tbody>{d.monthly.map((r:any)=><tr key={r.month}><td>{r.month}</td><td>{money(r.revenue)}</td><td>{money(r.pending)}</td></tr>)}</tbody></table></TableCard><TableCard title="Planos"><table><thead><tr><th>Plano</th><th>Matrículas</th><th>Receita</th></tr></thead><tbody>{d.plans.map((r:any)=><tr key={r.name}><td>{r.name}</td><td>{r.enrollments}</td><td>{money(r.revenue)}</td></tr>)}</tbody></table></TableCard><TableCard title="Formas de pagamento"><table><thead><tr><th>Método</th><th>Transações</th><th>Total</th></tr></thead><tbody>{d.methods.map((r:any)=><tr key={r.method}><td>{r.method}</td><td>{r.count}</td><td>{money(r.total)}</td></tr>)}</tbody></table></TableCard><TableCard title="Frequência — últimos 30 dias"><div className="bars">{d.attendance.map((r:any)=><div key={r.day}><span style={{height:`${Math.min(100,Number(r.checkins)*8+8)}%`}}></span><small>{r.day.slice(8)}</small></div>)}</div></TableCard></div></>}

function Team(){const [rows,setRows]=useState<any[]>([]),[modal,setModal]=useState(false),[b,setB]=useState<any>({role:'reception'});const load=()=>get('/team').then(setRows);useEffect(()=>{load()},[]);const save=async(e:React.FormEvent)=>{e.preventDefault();try{await post('/team',b);setModal(false);setB({role:'reception'});load()}catch(e:any){alert(e.message)}};return <><div className="page-head"><div><h2>Equipe</h2><p>Controle quem pode acessar e operar o MultiGym.</p></div><Button onClick={()=>setModal(true)}><Plus/> Novo usuário</Button></div><div className="card table-card"><table><thead><tr><th>Usuário</th><th>E-mail</th><th>Perfil</th><th>Status</th><th>Último acesso</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td><div className="person"><span className="avatar sm">{initial(r.name)}</span>{r.name}</div></td><td>{r.email}</td><td>{r.role}</td><td><Badge tone={r.status==='active'?'good':'neutral'}>{r.status}</Badge></td><td>{r.last_login_at?date(r.last_login_at):'Nunca'}</td></tr>)}</tbody></table></div>{modal&&<Modal title="Novo usuário" onClose={()=>setModal(false)}><form onSubmit={save}><Field label="Nome"><input required value={b.name||''} onChange={e=>setB({...b,name:e.target.value})}/></Field><Field label="E-mail"><input required type="email" value={b.email||''} onChange={e=>setB({...b,email:e.target.value})}/></Field><Field label="Senha"><input required minLength={8} type="password" value={b.password||''} onChange={e=>setB({...b,password:e.target.value})}/></Field><Field label="Perfil"><select value={b.role} onChange={e=>setB({...b,role:e.target.value})}><option value="manager">Gerente</option><option value="instructor">Instrutor</option><option value="reception">Recepção</option></select></Field><div className="modal-actions"><Button kind="secondary" onClick={()=>setModal(false)}>Cancelar</Button><Button type="submit">Criar usuário</Button></div></form></Modal>}</>}

function SettingsPage({user}:{user:User}){const [b,setB]=useState<any>(null),[saved,setSaved]=useState('');useEffect(()=>{get('/settings/gym').then(setB)},[]);if(!b)return <Loading/>;const save=async(e:React.FormEvent)=>{e.preventDefault();try{await put('/settings/gym',b);setSaved('Configurações salvas')}catch(e:any){alert(e.message)}};return <><div className="page-head"><div><h2>Configurações</h2><p>Identidade e dados operacionais da academia.</p></div></div><div className="settings-grid"><div className="card settings-nav"><button className="active">Dados da academia</button><button>Segurança</button><button>Preferências</button><button>Notificações</button><button>Plano e cobrança</button></div><form className="card settings-form" onSubmit={save}><h3>Dados da academia</h3><p className="muted">Essas informações aparecem no ambiente da equipe.</p><div className="form-grid"><Field label="Nome"><input value={b.name||''} onChange={e=>setB({...b,name:e.target.value})}/></Field><Field label="CNPJ"><input value={b.cnpj||''} onChange={e=>setB({...b,cnpj:e.target.value})}/></Field><Field label="Telefone"><input value={b.phone||''} onChange={e=>setB({...b,phone:e.target.value})}/></Field><Field label="E-mail"><input value={b.email||''} onChange={e=>setB({...b,email:e.target.value})}/></Field><Field label="Logo URL"><input value={b.logo_url||''} onChange={e=>setB({...b,logo_url:e.target.value})}/></Field><Field label="Fuso horário"><select value={b.timezone||'America/Sao_Paulo'} onChange={e=>setB({...b,timezone:e.target.value})}><option>America/Sao_Paulo</option><option>America/Fortaleza</option><option>America/Recife</option></select></Field></div><Button type="submit">Salvar alterações</Button>{saved&&<span className="save-ok">✓ {saved}</span>}</form></div></>}

function App(){const [user,setUser]=useState<User|null>(null),[page,setPage]=useState<Page>('dashboard'),[studentId,setStudentId]=useState<string|null>(null);useEffect(()=>{if(localStorage.getItem('multigym_token'))get('/me').then(r=>setUser(r.user)).catch(()=>localStorage.removeItem('multigym_token'))},[]);if(!user)return <Auth onLogin={setUser}/>;const logout=async()=>{try{await api('/auth/logout',{method:'POST'})}catch{}localStorage.removeItem('multigym_token');setUser(null)};let content:React.ReactNode; if(studentId)content=<StudentDetail id={studentId} onBack={()=>setStudentId(null)}/>;else switch(page){case'dashboard':content=<Dashboard go={setPage}/>;break;case'students':content=<Students onOpen={setStudentId}/>;break;case'plans':content=<Plans/>;break;case'enrollments':content=<Enrollments/>;break;case'workouts':content=<Workouts/>;break;case'finance':content=<Finance/>;break;case'products':content=<Products/>;break;case'services':content=<Services/>;break;case'sales':content=<Sales/>;break;case'cash':content=<Cash/>;break;case'checkin':content=<Checkin/>;break;case'agenda':content=<Agenda/>;break;case'reports':content=<Reports/>;break;case'team':content=<Team/>;break;case'settings':content=<SettingsPage user={user}/>;break;}return <Shell user={user} page={page} setPage={setPage} onLogout={logout}>{content}</Shell>}

createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);
